inline const float* heavy_hex_3x3_noisy_kick_ptm(int bond_id, float gamma) {
    int best = 0;
    float best_diff = fabsf(gamma - HEAVY_HEX_3x3_NOISY_KICK_GAMMAS[0]);
    for (int i = 1; i < HEAVY_HEX_3x3_NOISY_KICK_N_GAMMA; i++) {
        float diff = fabsf(gamma - HEAVY_HEX_3x3_NOISY_KICK_GAMMAS[i]);
        if (diff < best_diff) { best = i; best_diff = diff; }
    }
    if (best == 0) return HEAVY_HEX_3x3_NOISY_KICK_GAMMA1_0[bond_id];
    if (best == 1) return HEAVY_HEX_3x3_NOISY_KICK_GAMMA1_4[bond_id];
    return HEAVY_HEX_3x3_NOISY_KICK_GAMMA1_8[bond_id];
}
